export declare const schedulerStyles = "\n/* ---- \u5B9A\u65F6\u4EFB\u52A1\uFF08\u65B0\u529F\u80FD\u672C\u9636\u6BB5\uFF1B\u6837\u5F0F\u5BF9\u9F50\u7EC4\u5408\u7BA1\u7406 wf-combo \u4F53\u7CFB\uFF09 ---- */\n.wf-sched__form {\n  flex: 1.25;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  border-right: 1px solid var(--wf-border);\n  overflow: hidden;\n}\n\n.wf-sched__form-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 12px 14px;\n  scrollbar-width: thin;\n}\n\n.wf-sched__form-foot {\n  flex: none;\n  display: flex;\n  gap: 7px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-sched__form-foot .wf-btn {\n  flex: 1;\n  font-size: 11px;\n  padding: 6px 10px;\n}\n\n.wf-sched-field {\n  display: grid;\n  gap: 4px;\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-sched-field__label {\n  font-weight: 600;\n  color: var(--wf-ink);\n}\n\n.wf-sched-field__hint {\n  font-size: 9px;\n  line-height: 1.55;\n  color: var(--wf-ink-2);\n}\n\n.wf-sched-field select,\n.wf-sched-field input {\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n  font: inherit;\n  font-size: 12px;\n}\n\n.wf-sched-field select:focus,\n.wf-sched-field input:focus {\n  border-color: var(--wf-brand);\n}\n\n/* ---- \u8868\u5355\u5206\u7EC4\u4E0E\u5B57\u6BB5\u63A7\u4EF6 ---- */\n.wf-sched-group {\n  display: grid;\n  gap: 8px;\n  padding: 10px 12px;\n  border: 1px solid var(--wf-border);\n  border-radius: 11px;\n  background: var(--wf-layer-2);\n}\n\n.wf-sched-group h5 {\n  margin: 0;\n  font-size: 12px;\n  color: var(--wf-ink);\n}\n\n.wf-sched-radios {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.wf-sched-radio {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--wf-ink);\n  font-size: 11px;\n  cursor: pointer;\n}\n\n.wf-sched-radio input {\n  accent-color: var(--wf-brand);\n}\n\n.wf-sched-workspace {\n  margin-top: 6px;\n  font-variant-numeric: tabular-nums;\n}\n\n.wf-sched-dates {\n  display: flex;\n  gap: 7px;\n}\n\n.wf-sched-dates input {\n  flex: 1;\n  font-variant-numeric: tabular-nums;\n}\n\n.wf-sched-dates .wf-btn {\n  font-size: 12px;\n  padding: 5px 10px;\n}\n\n.wf-sched-days {\n  display: flex;\n  gap: 4px;\n  flex-wrap: wrap;\n}\n\n.wf-sched-day {\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer);\n  color: var(--wf-ink-2);\n  padding: 5px 0;\n  width: 32px;\n  font-size: 11px;\n  cursor: pointer;\n  font-weight: 600;\n}\n\n.wf-sched-day:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-ink);\n}\n\n.wf-sched-day.is-active {\n  border-color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 12%, var(--wf-layer));\n  color: var(--wf-brand);\n}\n\n.wf-sched-days .is-all {\n  width: auto;\n  padding: 5px 10px;\n}\n\n/* ---- \u91CD\u590D\u533A\u95F4\u7F16\u8F91 ---- */\n.wf-sched-ranges {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.wf-sched-ranges .wf-btn.is-ghost {\n  align-self: flex-start;\n  font-size: 10px;\n  padding: 3px 8px;\n}\n\n.wf-sched-range-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-sched-range-row input {\n  flex: 1;\n  min-width: 0;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer);\n  color: var(--wf-ink);\n  padding: 5px 7px;\n  outline: 0;\n  font: inherit;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n}\n\n.wf-sched-range-row input:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-sched-range-row .wf-btn {\n  padding: 3px 7px;\n  font-size: 11px;\n}\n\n.wf-sched-row2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n}\n\n/* ---- \u4EFB\u52A1\u5217\u8868\u72B6\u6001 ---- */\n.wf-sched-status-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px 14px;\n  font-size: 10px;\n  color: var(--wf-ink-2);\n}\n\n.wf-sched-status-cell {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.wf-sched-status-cell.is-error {\n  color: var(--wf-err);\n  white-space: normal;\n  width: 100%;\n}\n\n.wf-sched-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--wf-ink-2);\n  flex: none;\n  display: inline-block;\n}\n\n.wf-sched-dot.is-running {\n  background: var(--wf-ok);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-ok) 16%, transparent);\n}\n\n.wf-sched-dot.is-waiting {\n  background: #e6b23c;\n}\n\n.wf-sched-dot.is-paused {\n  background: var(--wf-ink-2);\n}\n\n.wf-sched-dot.is-error {\n  background: var(--wf-err);\n}\n\n.wf-sched-list-meta {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  font-size: 9px;\n  color: var(--wf-ink-2);\n}\n\n.wf-sched-enabled {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--wf-border);\n  color: var(--wf-ink);\n  font-size: 11px;\n}\n\n.wf-sched-enabled input {\n  accent-color: var(--wf-brand);\n}\n\n/* ---- \u53CC\u6708\u65E5\u5386\uFF08\u6837\u5F0F\u53C2\u8003\u7528\u6237\u65E5\u5386\u7D20\u6750\uFF09 ---- */\n.wf-cal-card {\n  display: grid;\n  gap: 8px;\n  padding: 10px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 12px;\n  background: var(--wf-layer);\n  box-shadow: 0 14px 40px color-mix(in srgb, var(--wf-ink) 16%, transparent);\n}\n\n.wf-cal-card__foot {\n  display: flex;\n  justify-content: flex-end;\n}\n\n.wf-cal-card__foot .wf-btn {\n  font-size: 11px;\n  padding: 5px 14px;\n}\n\n.wf-cal {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n  padding: 8px;\n  border-radius: 12px;\n  background: color-mix(in srgb, var(--wf-bg) 78%, transparent);\n}\n\n.wf-cal-month {\n  display: grid;\n  gap: 6px;\n  min-width: 0;\n}\n\n.wf-cal-month__head {\n  display: grid;\n  grid-template-columns: 26px 1fr 26px;\n  align-items: center;\n  gap: 4px;\n  color: var(--wf-ink);\n}\n\n.wf-cal-month__title {\n  font-size: 13px;\n  font-weight: 650;\n  text-align: center;\n  white-space: nowrap;\n}\n\n.wf-cal-nav {\n  border: 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  font-size: 15px;\n  line-height: 1;\n  padding: 4px;\n  cursor: pointer;\n  border-radius: 6px;\n}\n\n.wf-cal-nav:hover {\n  color: var(--wf-ink);\n  background: var(--wf-layer-2);\n}\n\n.wf-cal-nav.is-placeholder {\n  visibility: hidden;\n}\n\n.wf-cal-grid {\n  display: grid;\n  grid-template-columns: repeat(7, 1fr);\n  gap: 2px;\n}\n\n.wf-cal-week {\n  font-size: 11px;\n  font-weight: 650;\n  color: var(--wf-ink);\n  text-align: center;\n  padding: 2px 0;\n}\n\n.wf-cal-cell {\n  border: 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  height: 36px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 1px;\n  position: relative;\n  cursor: pointer;\n  padding: 0;\n}\n\n.wf-cal-cell:disabled {\n  cursor: default;\n}\n\n.wf-cal-cell.is-dim {\n  color: var(--wf-ink-3);\n}\n\n.wf-cal-cell:not(:disabled):hover .wf-cal-cell__num {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--wf-brand) 55%, transparent);\n}\n\n.wf-cal-cell__num {\n  display: grid;\n  place-items: center;\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  position: relative;\n  z-index: 1;\n  font-size: 12px;\n}\n\n.wf-cal-cell.is-start .wf-cal-cell__num,\n.wf-cal-cell.is-end .wf-cal-cell__num {\n  background: var(--wf-brand);\n  color: var(--wf-on-brand);\n}\n\n.wf-cal-cell__tag {\n  font-size: 7px;\n  line-height: 1;\n  color: var(--wf-ink-2);\n}\n\n.wf-cal-cell.is-start .wf-cal-cell__tag,\n.wf-cal-cell.is-end .wf-cal-cell__tag {\n  color: var(--wf-brand);\n  font-weight: 650;\n}\n\n.wf-cal-cell.is-today .wf-cal-cell__num {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--wf-ink) 55%, transparent);\n}\n\n/* ---- \u81EA\u5B9A\u4E49\u65F6\u95F4\u8F93\u5165\uFF08\u6587\u672C\u6309\u4F4D + \u53CC\u5217\u6ED1\u8F6E\uFF0C\u4E24\u6B21\u70B9\u51FB\u786E\u8BA4\uFF09 ---- */\n.wf-time {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  position: relative;\n  flex: 1;\n  min-width: 0;\n}\n\n.wf-time__field {\n  flex: 1;\n  min-width: 0;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer);\n  color: var(--wf-ink);\n  padding: 5px 7px;\n  outline: 0;\n  font: inherit;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n}\n\n.wf-time__field:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-time__clock {\n  border: 1px solid var(--wf-border);\n  background: var(--wf-layer);\n  color: var(--wf-ink-2);\n  border-radius: 7px;\n  padding: 5px 7px;\n  cursor: pointer;\n  font-size: 11px;\n}\n\n.wf-time__clock:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-ink);\n}\n\n.wf-time__picker {\n  position: absolute;\n  top: 100%;\n  left: 0;\n  z-index: 60;\n  display: flex;\n  gap: 2px;\n  margin-top: 4px;\n  padding: 6px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 10px;\n  background: var(--wf-layer);\n  box-shadow: 0 14px 38px color-mix(in srgb, var(--wf-ink) 16%, transparent);\n}\n\n.wf-time__col {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  max-height: 188px;\n  overflow: auto;\n  scrollbar-width: thin;\n  min-width: 46px;\n}\n\n.wf-time__opt {\n  border: 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  padding: 5px 8px;\n  border-radius: 7px;\n  cursor: pointer;\n}\n\n.wf-time__opt:hover {\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n}\n\n.wf-time__opt.is-active {\n  background: var(--wf-brand);\n  color: var(--wf-on-brand);\n  font-weight: 650;\n}\n";
